"""Generate docs/results.md from the JSON files in results/ (so the document cannot drift from the numbers)."""
import json
from pathlib import Path

R = Path("results"); L = lambda n: json.loads((R / n).read_text())
def row(name, d, keys=("recall@10", "ndcg@10", "recall@100", "ndcg@100")):
    cells = []
    for k in keys:
        v = d[k]; cells.append(f"{v['mean']:.4f} ({v['ci95'][0]:.4f} to {v['ci95'][1]:.4f})" if isinstance(v, dict) else f"{v:.4f}")
    return f"| {name} | " + " | ".join(cells) + " |"
H = "| System | Recall@10 | NDCG@10 | Recall@100 | NDCG@100 |\n|---|---|---|---|---|\n"
out = ["# Results\n", "All numbers are produced by the scripts in `scripts/` and stored as JSON in `results/`; this file is generated by `scripts/make_results_md.py`.\n"]

t = L("final_test.json"); n = {"popularity": "Popularity", "two_tower": "Two-tower alone", "itemknn": "Item-KNN alone", "dcn": "Full system, DCN-v2", "wide_deep": "Full system, Wide & Deep"}
out += [f"## Test window (scored once), {t['users']:,} users\n", t["protocol"] + ".\n", "Mean (95% bootstrap CI).\n", H + "\n".join(row(n[k], v) for k, v in t["systems"].items()) + "\n", "Paired differences (same users):\n",
        "| Comparison | Recall@10 | NDCG@10 |\n|---|---|---|\n" + "\n".join(f"| {k.replace('_minus_', ' minus ')} | {v['recall@10']['mean']:+.4f} ({v['recall@10']['ci95'][0]:+.4f} to {v['recall@10']['ci95'][1]:+.4f}) | {v['ndcg@10']['mean']:+.4f} ({v['ndcg@10']['ci95'][0]:+.4f} to {v['ndcg@10']['ci95'][1]:+.4f}) |" for k, v in t["paired"].items()) + "\n"]
a = t["ab_replay"]; c, tr = a["control_dcn"], a["treatment_wide_deep"]
out += ["### Simulated A/B replay (not live traffic)\n", a["note"] + ".\n",
        f"| Arm | Users | Impressions | Clicks | CTR |\n|---|---|---|---|---|\n| Control: DCN-v2 | {c['users']:,} | {c['impressions']:,} | {c['clicks']:,} | {c['ctr']:.4%} |\n| Treatment: Wide & Deep | {tr['users']:,} | {tr['impressions']:,} | {tr['clicks']:,} | {tr['ctr']:.4%} |\n",
        f"CTR difference (treatment minus control) {a['ctr_diff_treatment_minus_control']:+.5f}, user-bootstrap 95% CI {a['diff_ci95_user_bootstrap'][0]:+.5f} to {a['diff_ci95_user_bootstrap'][1]:+.5f}; two-proportion z = {a['two_proportion_z']}, p = {a['p_value_two_sided']}. No significant difference.\n"]

v = L("retrieval_val_full_warm.json"); k = L("itemknn_val_warm.json"); r = L("ranker_union_cv_val.json"); r1 = L("ranker_cv_val.json")
out += ["## Validation window (model development)\n", f"Warm users: {v['warm_users']:,}. Retrievers on the full warm cohort:\n", "| Retriever | Recall@10 | NDCG@10 | Recall@100 | NDCG@100 |\n|---|---|---|---|---|",
        "| Popularity | 0.0283 | 0.0832 | 0.1333 | 0.0962 |",
        f"| Two-tower (exact search) | {v['two_tower']['recall@10']:.4f} | {v['two_tower']['ndcg@10']:.4f} | {v['two_tower']['recall@100']:.4f} | {v['two_tower']['ndcg@100']:.4f} |",
        f"| Item-KNN | {k['recall@10']:.4f} | {k['ndcg@10']:.4f} | {k['recall@100']:.4f} | {k['ndcg@100']:.4f} |\n",
        f"Rankers, 5-fold cross-validation by user, {r['candidates_per_user']} two-source candidates per user (mean and 95% CI):\n", H + "\n".join(row(nm, r["models"][key]) for nm, key in (("Two-tower alone", "two_tower_alone"), ("Item-KNN alone", "itemknn_alone"), ("DCN-v2 over union", "dcn_union"), ("Wide & Deep over union", "wide_deep_union"))) + "\n",
        "Rankers over two-tower-only candidates (first experiment, 200 candidates):\n", H + "\n".join(row(nm, r1["models"][key]) for nm, key in (("Retriever order", "retriever"), ("DCN-v2", "dcn"), ("Wide & Deep", "wide_deep"))) + "\n"]
i = L("faiss_index_eval.json")
out += ["## FAISS index (validation, 5,083 users, K=100)\n", "| Index | Recall@100 | NDCG@100 | p50 latency (ms) | p99 latency (ms) | Top-100 overlap with exact |\n|---|---|---|---|---|---|",
        f"| Flat (exact) | {i['flat_exact']['recall@100']} | {i['flat_exact']['ndcg@100']} | {i['flat_exact']['latency_ms_p50']} | {i['flat_exact']['latency_ms_p99']} | 1.0 |"]
for ef in (16, 64, 128, 256):
    d = i[f"hnsw_ef{ef}"]; out.append(f"| HNSW efSearch={ef} (M=32, efConstruction=200) | {d['recall@100']} | {d['ndcg@100']} | {d['latency_ms_p50']} | {d['latency_ms_p99']} | {d['top100_overlap_with_exact']} |")
out += ["\nThe search widens efSearch per query to at least k + the user's rated-item count, so the setting has no visible effect; see `docs/limitations.md` for what this does and does not show.\n"]
s = L("serving_eval_dev.json"); co = L("cohorts_val.json")
out += ["## Serving path (508 held-out validation users)\n", f"DCN-v2 NDCG@10 {s['dcn']['ndcg@10']}, Wide & Deep {s['wide_deep']['ndcg@10']}, matching the offline evaluation. Latency (2-CPU container): DCN-v2 p50 {s['dcn']['latency_ms_cold_cache_p50']} ms, p95 {s['dcn']['latency_ms_cold_cache_p95']} ms uncached; Redis hit p50 {s['redis_cached_p50_ms']} ms, p95 {s['redis_cached_p95_ms']} ms.\n",
        "## Cold-start cohorts (validation)\n", "| Cohort | Users with relevant items | Evaluated | Route | System NDCG@10 | Popularity NDCG@10 |\n|---|---|---|---|---|---|"]
for nm, d in co.items():
    out.append(f"| {nm} | {d['users_in_cohort']:,} | {d['users_evaluated']:,} | {d['route_used']} | {d['system']['ndcg@10']} | {d['popularity']['ndcg@10']} |")
Path("docs/results.md").write_text("\n".join(out) + "\n"); print("wrote docs/results.md")
